package XML::Simple;

# --- INCLUDES ---
use strict;
use warnings;
use warnings::register;
use Carp;
use Scalar::Util qw();
require Exporter;
use vars qw($VERSION @ISA @EXPORT @EXPORT_OK $PREFERRED_PARSER);
require File::Basename;
require XML::SAX;
require XML::Parser;
require Storable;
require Storable;
require Storable;
require XML::NamespaceSupport;
require IO::Handle;
require XML::SAX;
require File::Basename;
require File::Spec;

# --- METRICS ---
# line_count: 8
# cyclomatic_complexity: 1
# max_nesting_depth: 4

# --- HINTS ---
# external_call: XML::Parser->new
# method_chain: var: $xp holds XML::Parser object
# method_chain: call: XML::Parser->new
# method_chain: need: $self->{opt}
# method_chain: need: $xp->setHandlers
# method_chain: chain: $xp (XML::Parser) calls setHandlers
# --- FUNCTION: new_xml_parser ---
sub new_xml_parser {
  my($self) = @_;

  my $xp = XML::Parser->new(Style => 'Tree', @{$self->{opt}->{parseropts}});
  $xp->setHandlers(ExternEnt => sub {return $_[2]});

  return $xp;
}

