require XML::SAX;
require File::Basename;
require File::Spec;

# --- METRICS ---
# line_count: 182
# cyclomatic_complexity: 45
# max_nesting_depth: 8

# --- HINTS ---
# if/else: branches
# for/while: loop
# external_call: UNIVERSAL::isa
# method_chain: need: $self->{opt}
# method_chain: need: $self->new_hashref
